'use strict';
(()=>{
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let lang='en';try{if(localStorage.getItem('tripol-language')==='es')lang='es'}catch{}
const chosen=new URLSearchParams(location.search).get('lang');if(chosen==='en'||chosen==='es')lang=chosen;
const root=document.body.dataset.docRoot||'./';
// A freshly loaded script must also load its matching stylesheet.
for(const link of document.querySelectorAll('link[rel="stylesheet"]')){const u=new URL(link.href,location.href);if(u.pathname.endsWith('/docs/docs.css')&&u.searchParams.get('v')!=='learning-r3.1'){u.searchParams.set('v','learning-r3.1');link.href=u.href}}
function localLinks(){for(const a of $$('a[href]')){const raw=a.getAttribute('href');if(!raw||raw.startsWith('#')||/^(https?:|mailto:)/i.test(raw)&&a.origin!==location.origin)continue;const u=new URL(raw,location.href);if(!u.pathname.endsWith('.html'))continue;u.searchParams.set('lang',lang);a.href=u.href;}}
// Shared navigation and current release label on all reference pages.
const side=document.querySelector('#doc-side');
side.querySelector('.side-kicker').textContent='OVERDRIVE / 0.26.0';
const crumb=document.querySelector('.crumb > span:last-child');if(crumb&&/^0\.(24|25)$/.test(crumb.textContent))crumb.textContent='0.26';
const meta=document.querySelector('.lib-meta > span:first-child');if(meta&&/^(ASCENSION 0\.24|EVOLUTION 0\.25)$/.test(meta.textContent))meta.textContent='OVERDRIVE 0.26';
const guide=side.querySelector('nav[aria-label="Guides"]');
for(const [file,label] of [['genesis','GENESIS R2'],['update','UPDATE R1']]){let a=guide.querySelector('a[href$="'+file+'.html"]');if(!a){a=document.createElement('a');a.href=root+file+'.html';guide.append(a);}a.textContent=label;}
const libs=side.querySelector('.side-libs');
for(const [name,before,count] of [['queue','random',7],['stack','stats',7],['bitset','buffer',6],['profiler','queue',2]]){if(!libs.querySelector('a[href$="/'+name+'.html"]')){const a=document.createElement('a');a.href=root+'libraries/'+name+'.html';const label=document.createElement('span');label.textContent=name;const n=document.createElement('small');n.textContent=String(count);a.append(label,n);libs.insertBefore(a,libs.querySelector('a[href$="/'+before+'.html"]'));}}
for(const a of side.querySelectorAll('nav a')){a.removeAttribute('aria-current');if(new URL(a.href,location.href).pathname===location.pathname)a.setAttribute('aria-current','page');}
const translate=(en,es)=>lang==='es'?es:en;
let labels=[], placeholders=[];
function registerLabels(){labels=$$('[data-es]').map(el=>({el,en:el.textContent,es:el.dataset.es}));placeholders=$$('[data-placeholder-es]').map(el=>({el,en:el.placeholder,es:el.dataset.placeholderEs}));}
function docsTokens(source,mode='tripol'){
 const keywords=new Set('show let const func return if else while for in repeat break continue assert and or not import struct try catch finally throw scratch'.split(' '));
 const types=new Set('int float bool string ints list string_list bool_list float_list'.split(' '));
 const builtins=new Set('input input_int len sum range abs min max sqrt text slice parse_int'.split(' '));
 const terminal=['cmd','sh','bash','shell','powershell','ps1'].includes(mode);
 const pattern=terminal?/(?:https?:\/\/[^\s"'<>]+|#[^\r\n]*|"(?:\\.|[^"\\\r\n])*"?|'(?:\\.|[^'\\\r\n])*'?|\$[\w:]+|--?[\w][\w-]*|\b[\w.-]+(?:[\/\\][\w./\\-]+)+|\b\d+(?:\.\d+)?\b|[A-Za-z_][A-Za-z_0-9.-]*|[=|&<>]+|\s+|.)/gu:/(?:\/\/[^\r\n]*|#[^\r\n]*|f?"(?:\\.|[^"\\\r\n])*"?|'(?:\\.|[^'\\\r\n])*'?|\b(?:0[xX][\da-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)\b|[A-Za-z_][A-Za-z_0-9]*|==|!=|<=|>=|=>|->|\+=|-=|\*=|\/=|%=|&&|\|\||[+\-*/%=<>!]|[{}()[\],.:;]|\s+|.)/gu;
 const out=[];const emit=(v,k='plain')=>{if(v)out.push({v,k})};
 for(const m of source.matchAll(pattern)){
  const v=m[0],after=source.slice(m.index+v.length);let k='plain';
  if(v.startsWith('#')||(!terminal&&v.startsWith('//')))k='comment';
  else if(!terminal&&v.startsWith('f"')){
   let start=0,i=2;
   while(i<v.length){
    if(v[i]==='\\'){i+=2;continue}
    if(v.slice(i,i+2)==='{{'||v.slice(i,i+2)==='}}'){i+=2;continue}
    if(v[i]==='{'){const end=v.indexOf('}',i+1);if(end<0)break;const field=v.slice(i+1,end);if(!field.includes('{')&&!field.includes('\\')&&!field.includes('"')){emit(v.slice(start,i),'string');emit('{','interpolation');out.push(...docsTokens(field,'tripol'));emit('}','interpolation');start=end+1;i=start;continue}}
    i++;
   }
   emit(v.slice(start),'string');continue;
  }
  else if(v.startsWith('"')||v.startsWith("'"))k='string';
  else if(/^\d/.test(v))k='number';
  else if(terminal){
   if(/^https?:\/\//.test(v))k='path';
   else if(v.startsWith('$')||/^[A-Z_][A-Z_0-9]+$/.test(v)&&after.startsWith('='))k='variable';
   else if(/^--?[\w]/.test(v))k='option';
   else if(/^(tripol|git|go|python|python3|cd|mkdir|cp|curl|node|rustc|cargo|npm|cmake|notepad|powershell|cmd|Read-Host|Get-ChildItem|Set-Location|echo|chmod|make)$/i.test(v))k='function';
   else if(/[\/\\]/.test(v))k='path';
   else if(/^[=|&<>]+$/.test(v))k='operator';
  }else{
   if(v==='true'||v==='false'||v==='null')k='literal';
   else if(keywords.has(v))k='keyword';
   else if(types.has(v))k='type';
   else if(builtins.has(v)||/^[A-Za-z_]/.test(v)&&/^\s*\(/.test(after))k='function';
   else if(v==='tripol'||v==='vault'||/^[A-Za-z_]/.test(v)&&/^\s*\./.test(after))k='namespace';
   else if(/^[+\-*/%=<>!&|]/.test(v))k='operator';
   else if(/^[{}()[\],.:;]$/.test(v))k='punct';
  }
  emit(v,k);
 }
 return out;
}
function codeMode(code){
 const pre=code.closest('pre');const explicit=[...code.classList,...(pre?[...pre.classList]:[])].find(c=>c.startsWith('language-'));
 if(explicit)return explicit.slice(9);
 if(pre?.classList.contains('signature'))return 'tripol';
 const s=code.textContent.trim();
 if(/^(?:tripol|git|go|python3?|cd|rustc|cargo|npm|cmake|curl|mkdir|cp|notepad|powershell)\s|^--?[\w-]|^\$[\w:]+|^[A-Z_][A-Z_0-9]+=/.test(s))return 'sh';
 if(/^(?:func|import|show|let|const|struct|if|for|while|try|scratch)\b|^[A-Za-z_]\w*\.[A-Za-z_]\w*|[=()[\]{}]/.test(s))return 'tripol';
 return pre?'text':'tripol';
}
function highlightDocs(){
 for(const code of [...document.querySelectorAll('.docs-article code, .docs-article pre:not(:has(code))')]){
  if(code.closest('.doc-live-panel'))continue;
  const raw=code.textContent,mode=codeMode(code);
  if(raw.length>100000||!raw||['text','output','plaintext'].includes(mode))continue;
  if(code.dataset.syntaxReady==='yes'&&code._tripolSource===raw&&code.querySelector('.doc-tok'))continue;
  if([...code.children].some(c=>!c.classList.contains('doc-tok')))continue;
  const frag=document.createDocumentFragment();
  for(const t of docsTokens(raw,mode)){if(t.k==='plain'){frag.append(document.createTextNode(t.v));continue}const span=document.createElement('span');span.className='doc-tok doc-tok-'+t.k;span.textContent=t.v;frag.append(span)}
  code.replaceChildren(frag);code.dataset.syntaxReady='yes';code._tripolSource=raw;
 }
}


// DOCS LIVE R1 — lazy editors, real compiler workers, no automatic execution.
const livePanels=[];let liveJob=null;
function liveElement(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function liveLabel(e,en,es){e.textContent=translate(en,es);e._liveLabel=[en,es];return e}
function liveButton(en,es,action,cls='doc-copy'){const b=liveLabel(liveElement('button',cls),en,es);b.type='button';b.addEventListener('click',action);return b}
function liveStatus(p,en,es,kind=''){p.message=[en,es];p.status.textContent=translate(en,es);p.status.dataset.state=kind}
function liveRefresh(){for(const e of $$('.doc-live-action,.doc-live-panel button,.doc-live-label,.doc-live-help'))if(e._liveLabel)e.textContent=translate(...e._liveLabel);for(const p of livePanels){if(p.message)p.status.textContent=translate(...p.message);p.input.placeholder=translate('One line per input()','Una línea por input()');p.editor.setAttribute('aria-label',translate('Editable TRIPOL example','Ejemplo TRIPOL editable'));p.input.setAttribute('aria-label',translate('Program input','Entrada del programa'));p.output.setAttribute('aria-label',translate('Program output','Salida del programa'))}}
function livePlayground(source){if(source.length>32768){toast(translate('Source exceeds 32 KiB','El código supera 32 KiB'));return}const u=new URL(root+'../playground/index.html',location.href);u.searchParams.set('lang',lang);u.hash='code='+encodeURIComponent(source);window.open(u.href,'_blank','noopener,noreferrer')}
function livePaint(p){const frag=document.createDocumentFragment();for(const t of docsTokens(p.editor.value)){if(t.k==='plain')frag.append(document.createTextNode(t.v));else{const el=liveElement('span','doc-tok doc-tok-'+t.k,t.v);frag.append(el)}}frag.append(document.createTextNode('\n'));p.highlight.replaceChildren(frag);p.stack.classList.add('painted');liveScroll(p)}
function liveScroll(p){p.highlight.scrollTop=p.editor.scrollTop;p.highlight.scrollLeft=p.editor.scrollLeft}
function liveStop(p,message=true){if(!liveJob||liveJob.panel!==p)return;const j=liveJob;liveJob=null;clearTimeout(j.timer);j.worker.terminate();p.run.disabled=false;p.stop.hidden=true;if(message)liveStatus(p,'Stopped','Detenido')}
function liveFiles(p,files=[]){
 p.files.replaceChildren();p.files.hidden=true;
 for(const file of files.slice(0,64)){
  if(typeof file.name!=='string'||!(file.bytes instanceof Uint8Array))continue;
  const row=liveElement('div','doc-live-file-row');row.append(liveElement('span','',file.name+' · '+file.bytes.length+' B'));
  row.append(liveButton('Download','Descargar',()=>{const u=URL.createObjectURL(new Blob([file.bytes],{type:file.name.endsWith('.wav')?'audio/wav':'application/octet-stream'}));const a=document.createElement('a');a.href=u;a.download=file.name.split('/').at(-1);a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}));p.files.append(row)
 }
 p.files.hidden=!p.files.children.length
}
function liveRun(p){liveFiles(p);
 if(liveJob)liveStop(liveJob.panel);
 const source=p.editor.value;
 if(new TextEncoder().encode(source).length>32768||new TextEncoder().encode(p.input.value).length>32768){liveStatus(p,'Input exceeds 32 KiB','La entrada supera 32 KiB','error');return}
 p.output.textContent='';p.run.disabled=true;p.stop.hidden=false;liveStatus(p,'Compiling with Web Engine R3…','Compilando con Web Engine R3…');
 let worker;try{worker=new Worker(new URL(root+'../playground/web-worker-r3.1.js',location.href))}catch(e){p.run.disabled=false;p.stop.hidden=true;liveStatus(p,'Compiler worker unavailable','Worker del compilador no disponible','error');p.output.textContent=String(e.message||e);return}
 const job={panel:p,worker,timer:null};liveJob=job;
 worker.onmessage=({data})=>{if(liveJob!==job)return;liveStop(p,false);p.output.textContent=(data.output||'')+(data.ok?'':'\n'+translate('Error: ','Error: ')+String(data.error||'Unknown error'));if(data.ok){if(Array.isArray(data.files))liveFiles(p,data.files);const time=Number(data.compileMs||0).toFixed(1)+' ms'+(data.build?' · '+data.build.slice(0,7):'');liveStatus(p,'WASM R3 · compiled in '+time,'WASM R3 · compilado en '+time,'ok')}else liveStatus(p,'Compiler/runtime diagnostic · no fallback','Diagnóstico del compilador/runtime · sin sustitución','error')};
 worker.onerror=()=>{if(liveJob!==job)return;liveStop(p,false);liveStatus(p,'Web Engine unavailable','Web Engine no disponible','error');p.output.textContent=translate('The compiler worker could not start. Open in Playground or try again.','No se pudo iniciar el compilador. Abre en Playground o vuelve a intentar.')};
 job.timer=setTimeout(()=>{if(liveJob!==job)return;liveStop(p,false);liveStatus(p,'Execution time limit (15 s)','Límite de ejecución (15 s)','error')},15000);
 try{worker.postMessage({source,input:p.input.value,compileOnly:false})}catch(e){liveStop(p,false);liveStatus(p,'Could not send source','No se pudo enviar el código','error');p.output.textContent=String(e.message||e)}
}
function makeLivePanel(source,original,trigger){
 const p={original,source};const panel=liveElement('section','doc-live-panel');p.panel=panel;panel.hidden=true;
 const toolbar=liveElement('div','doc-live-toolbar');const filename=liveElement('span','doc-live-file','example.tri');const actions=liveElement('div','doc-live-tools');toolbar.append(filename,actions);
 p.run=liveButton('▶ Run','▶ Ejecutar',()=>liveRun(p),'doc-live-run');
 p.stop=liveButton('Stop','Detener',()=>liveStop(p));p.stop.hidden=true;
 const reset=liveButton('Reset','Restaurar',()=>{liveStop(p,false);p.editor.value=p.original;p.input.value='';liveFiles(p);p.output.textContent='';livePaint(p);liveStatus(p,'Ready','Listo')});
 const open=liveButton('Playground ↗','Playground ↗',()=>livePlayground(p.editor.value));
 const close=liveButton('Close','Cerrar',()=>{liveStop(p);panel.hidden=true;source.hidden=false;trigger.setAttribute('aria-expanded','false');trigger.focus()});
 actions.append(p.run,p.stop,reset,open,close);
 p.stack=liveElement('div','doc-live-stack');p.highlight=liveElement('pre','doc-live-highlight');p.highlight.setAttribute('aria-hidden','true');p.editor=liveElement('textarea','doc-live-editor');p.editor.spellcheck=false;p.editor.autocapitalize='off';p.editor.setAttribute('autocorrect','off');p.editor.setAttribute('wrap','off');p.editor.maxLength=32768;p.editor.value=original;p.editor.setAttribute('aria-label',translate('Editable TRIPOL example','Ejemplo TRIPOL editable'));p.stack.append(p.highlight,p.editor);
 const inputBox=liveElement('details','doc-live-input');inputBox.append(liveLabel(liveElement('summary','doc-live-label'),'Optional input','Entrada opcional'));p.input=liveElement('textarea','doc-live-stdin');p.input.rows=2;p.input.maxLength=32768;inputBox.append(p.input);inputBox.open=/\binput(?:_int)?\s*\(/.test(original);
 const consoleBox=liveElement('div','doc-live-console');p.status=liveElement('div','doc-live-status');p.status.setAttribute('role','status');p.output=liveElement('pre','doc-live-output');p.output.setAttribute('aria-live','polite');p.files=liveElement('div','doc-live-files');p.files.hidden=true;consoleBox.append(p.status,p.output,p.files);
 const help=liveLabel(liveElement('p','doc-live-help'),'Runs with the real Web Engine R3. Unsupported browser features report a compiler error.','Ejecuta con Web Engine R3 real. Las funciones no compatibles muestran el error del compilador.');
 panel.append(toolbar,p.stack,inputBox,consoleBox,help);source.after(panel);livePanels.push(p);
 p.editor.addEventListener('input',()=>{livePaint(p);if(/\binput(?:_int)?\s*\(/.test(p.editor.value))inputBox.open=true});
 p.editor.addEventListener('scroll',()=>liveScroll(p));
 p.editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();liveRun(p)}else if(e.key==='Tab'&&!e.shiftKey){e.preventDefault();p.editor.setRangeText('    ',p.editor.selectionStart,p.editor.selectionEnd,'end');livePaint(p)}else if(e.key==='Escape'&&liveJob?.panel===p)liveStop(p)});
 liveStatus(p,'Ready · Ctrl + Enter','Listo · Ctrl + Enter');liveRefresh();
 return p
}
function installLive(source,host,original){
 if(!original||original.length>32768)return;
 let p;const button=liveButton('Try it','Probar',()=>{if(!p)p=makeLivePanel(source,original,button);if(!p.panel.hidden){liveStop(p);p.panel.hidden=true;source.hidden=false;button.setAttribute('aria-expanded','false');return}source.hidden=true;p.panel.hidden=false;button.setAttribute('aria-expanded','true');livePaint(p);p.editor.focus()},'doc-copy doc-live-action');
 button.setAttribute('aria-expanded','false');host.append(button)
}
function installAllLive(){
 for(const pre of $$('.docs-article pre')){
  // Function signatures and library implementation source are reference-only.
  if(pre.classList.contains('signature')||pre.closest('.function-card'))continue;
  if(document.querySelector('.doc-lib-guide[data-web-status="compiler-rejected"]'))continue;
  if(codeMode(pre.querySelector('code')||pre)!=='tripol')continue;
  const head=pre.closest('.code-shell')?.querySelector('.code-head');if(!head)continue;
  let actions=head.querySelector('.doc-code-actions');if(!actions){actions=liveElement('div','doc-code-actions');const copy=head.querySelector('.doc-copy');if(copy)actions.append(copy);head.append(actions)}
  installLive(pre,actions,pre.textContent);
 }
}
window.addEventListener('pagehide',()=>{if(liveJob)liveStop(liveJob.panel,false)});

function apply(){document.documentElement.lang=lang;labels.forEach(({el,en,es})=>el.textContent=translate(en,es));placeholders.forEach(({el,en,es})=>el.placeholder=translate(en,es));$('#doc-lang').textContent=lang==='en'?'ES':'EN';$('#doc-lang').setAttribute('aria-label',translate('Switch to Spanish','Cambiar a inglés'));try{localStorage.setItem('tripol-language',lang)}catch{};try{const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u.href)}catch{};localLinks();highlightDocs();liveRefresh();buildToc();if($('#doc-search').open)renderSearch();}
let timer;function toast(msg){const t=$('#doc-toast');t.textContent=msg;t.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('visible'),1800)}
const LEARNING_GUIDES={"math.square":{"en":"Multiply a number by itself.","es":"Multiplica un número por sí mismo.","body":"show math.square(5)","out":"25"},"math.cube":{"en":"Multiply a number by itself three times.","es":"Multiplica un número por sí mismo tres veces.","body":"show math.cube(3)","out":"27"},"math.clamp":{"en":"Keep a number within two limits.","es":"Mantiene un número entre dos límites.","body":"show math.clamp(120, 0, 100)","out":"100","noteEn":"Use a lower limit no greater than the upper limit.","noteEs":"El límite inferior no debe superar el superior."},"math.power":{"en":"Raise an integer to a nonnegative exponent.","es":"Eleva un entero a un exponente no negativo.","body":"show math.power(2, 4)","out":"16"},"math.gcd":{"en":"Find the greatest common divisor of two integers.","es":"Calcula el máximo común divisor de dos enteros.","body":"show math.gcd(12, 18)","out":"6"},"math.root":{"en":"Calculate the square root of a nonnegative decimal.","es":"Calcula la raíz cuadrada de un decimal no negativo.","body":"show math.root(81.0)","out":"9.000000"},"math.pi":{"en":"Return the mathematical constant pi.","es":"Devuelve la constante matemática pi.","body":"show math.pi()","out":"3.141593"},"math.percent":{"en":"Calculate a percentage of a number.","es":"Calcula un porcentaje de un número.","body":"show math.percent(200.0, 10.0)","out":"20.000000"},"math.sqrt_value":{"en":"Calculate a square root, just like math.root.","es":"Calcula una raíz cuadrada, igual que math.root.","body":"show math.sqrt_value(25.0)","out":"5.000000"},"math.absolute":{"en":"Return the distance of an integer from zero.","es":"Devuelve la distancia de un entero respecto a cero.","body":"show math.absolute(-8)","out":"8"},"math.minimum":{"en":"Return the smaller integer.","es":"Devuelve el menor de dos enteros.","body":"show math.minimum(3, 8)","out":"3"},"math.maximum":{"en":"Return the larger integer.","es":"Devuelve el mayor de dos enteros.","body":"show math.maximum(3, 8)","out":"8"},"arrays.make":{"en":"Create an array filled with a single value.","es":"Crea un arreglo lleno del mismo valor.","body":"show arrays.make(3, 7)","out":"[7, 7, 7]"},"arrays.total":{"en":"Sum every integer in an array.","es":"Suma todos los enteros de un arreglo.","body":"a = [1, 2, 3]\nshow arrays.total(a)","out":"6"},"arrays.count":{"en":"Count occurrences of a value.","es":"Cuenta las apariciones de un valor.","body":"a = [2, 5, 2]\nshow arrays.count(a, 2)","out":"2"},"arrays.contains":{"en":"Check whether a value appears in an array.","es":"Comprueba si un valor aparece en un arreglo.","body":"a = [1, 2, 3]\nshow arrays.contains(a, 2)","out":"true"},"arrays.reversed":{"en":"Return a new array in reverse order.","es":"Devuelve un arreglo nuevo en orden inverso.","body":"a = [1, 2, 3]\nshow arrays.reversed(a)","out":"[3, 2, 1]"},"arrays.copy":{"en":"Create an independent copy of an array.","es":"Crea una copia independiente de un arreglo.","body":"a = [1, 2]\nb = arrays.copy(a)\nb[0] = 9\nshow a, b","out":"[1, 2] [9, 2]"},"arrays.length":{"en":"Count elements in an array.","es":"Cuenta los elementos de un arreglo.","body":"a = [10, 20, 30]\nshow arrays.length(a)","out":"3"},"arrays.copy_into":{"en":"Copy values into an existing dynamic array of equal length.","es":"Copia valores a un arreglo dinámico existente de igual longitud.","body":"source = [4, 7]\ndestination = ints(2)\nshow arrays.copy_into(destination, source)\nshow destination","out":"true\n[4, 7]","noteEn":"Returns false if lengths differ; the destination is unchanged.","noteEs":"Devuelve false si las longitudes difieren; el destino no cambia."},"collections.append":{"en":"Return a new array with an extra element at the end.","es":"Devuelve un arreglo nuevo con un elemento adicional al final.","body":"a = [1, 2]\nshow collections.append(a, 3)","out":"[1, 2, 3]","noteEn":"The original array is not modified.","noteEs":"El arreglo original no cambia."},"collections.concat":{"en":"Join two arrays into a new one.","es":"Une dos arreglos en uno nuevo.","body":"a = [1, 2]\nb = [3, 4]\nshow collections.concat(a, b)","out":"[1, 2, 3, 4]"},"collections.part":{"en":"Copy a range, including start but excluding end.","es":"Copia un intervalo, incluyendo start pero excluyendo end.","body":"a = [10, 20, 30, 40]\nshow collections.part(a, 1, 3)","out":"[20, 30]"},"collections.remove_at":{"en":"Copy an array without an indexed element.","es":"Copia un arreglo sin el elemento indicado.","body":"a = [10, 20, 30]\nshow collections.remove_at(a, 1)","out":"[10, 30]"},"collections.insert":{"en":"Make a new array with a value inserted at an index.","es":"Crea un arreglo nuevo insertando un valor en un índice.","body":"a = [10, 30]\nshow collections.insert(a, 1, 20)","out":"[10, 20, 30]"},"collections.equal":{"en":"Check whether two arrays contain the same ordered values.","es":"Comprueba si dos arreglos contienen los mismos valores en el mismo orden.","body":"a = [1, 2]\nb = [1, 2]\nshow collections.equal(a, b)","out":"true"},"text.size":{"en":"Count UTF-8 bytes, not necessarily visible characters.","es":"Cuenta bytes UTF-8, no necesariamente caracteres visibles.","body":"show text.size(\"TRIPOL\")","out":"6"},"text.empty":{"en":"Check whether a string is empty.","es":"Comprueba si una cadena está vacía.","body":"show text.empty(\"\")","out":"true"},"text.from_int":{"en":"Convert an integer to text.","es":"Convierte un entero en texto.","body":"show text.from_int(42)","out":"42"},"text.to_int":{"en":"Convert valid integer text into a number.","es":"Convierte texto entero válido en un número.","body":"show text.to_int(\"42\") + 1","out":"43"},"text.part":{"en":"Copy bytes from start (included) to end (excluded).","es":"Copia bytes desde start (incluido) hasta end (excluido).","body":"show text.part(\"TRIPOL\", 0, 3)","out":"TRI","noteEn":"UTF-8 characters may use several bytes.","noteEs":"Los caracteres UTF-8 pueden ocupar varios bytes."},"text.starts_with":{"en":"Check whether text begins with a prefix.","es":"Comprueba si un texto comienza por un prefijo.","body":"show text.starts_with(\"TRIPOL\", \"TRI\")","out":"true"},"text.ends_with":{"en":"Check whether text ends with a suffix.","es":"Comprueba si un texto termina con un sufijo.","body":"show text.ends_with(\"main.tri\", \".tri\")","out":"true"},"text.index_of":{"en":"Find the first byte index of a substring, or -1.","es":"Encuentra el primer índice por bytes de un fragmento, o -1.","body":"show text.index_of(\"TRIPOL\", \"POL\")","out":"3"},"text.contains":{"en":"Check whether text contains a substring.","es":"Comprueba si un texto contiene un fragmento.","body":"show text.contains(\"Hello TRIPOL\", \"TRIPOL\")","out":"true"},"datetime.leap":{"en":"Check whether a year has 366 days.","es":"Comprueba si un año es bisiesto y tiene 366 días.","body":"show datetime.leap(2024)","out":"true"},"datetime.days_in_month":{"en":"Count the days in a month and year.","es":"Devuelve cuántos días tiene un mes de un año concreto.","body":"show datetime.days_in_month(2024, 2)","out":"29"},"datetime.valid":{"en":"Check whether a date exists.","es":"Comprueba si una fecha es válida.","body":"show datetime.valid(2024, 2, 29)","out":"true"},"datetime.day_of_year":{"en":"Find the position of a day within its year.","es":"Devuelve la posición de un día dentro de su año.","body":"show datetime.day_of_year(2024, 2, 1)","out":"32"},"datetime.ordinal":{"en":"Return the day number counted from year 1.","es":"Devuelve el número de día contado desde el año 1."},"datetime.weekday":{"en":"Return a weekday number, with Monday = 1.","es":"Devuelve el número del día de la semana, con lunes = 1.","body":"show datetime.weekday(2024, 1, 1)","out":"1"},"datetime.days_between":{"en":"Calculate the signed difference in days between dates.","es":"Calcula la diferencia con signo en días entre fechas.","body":"show datetime.days_between(2024, 1, 1, 2024, 1, 3)","out":"2"},"json.quote":{"en":"Escape text and surround it with JSON quotes.","es":"Escapa un texto y lo rodea de comillas JSON.","body":"show json.quote(\"Hola \\\"TRIPOL\\\"\")","out":"\"Hola \\\"TRIPOL\\\"\"","noteEn":"Input must be valid UTF-8, at most 512 bytes.","noteEs":"La entrada debe ser UTF-8 válido, de hasta 512 bytes."},"json.integer":{"en":"Convert an integer to JSON numeric text.","es":"Convierte un entero en texto numérico JSON.","body":"show json.integer(-42)","out":"-42","noteEn":"","noteEs":""},"json.boolean":{"en":"Convert a boolean into JSON text.","es":"Convierte un booleano en texto JSON.","body":"show json.boolean(true)\nshow json.boolean(false)","out":"true\nfalse","noteEn":"","noteEs":""},"json.pair":{"en":"Create a JSON object containing one string property.","es":"Crea un objeto JSON con una propiedad de texto.","body":"show json.pair(\"name\", \"TRIPOL\")","out":"{\"name\":\"TRIPOL\"}","noteEn":"Both key and value are strings, not raw JSON values.","noteEs":"La clave y el valor son textos, no valores JSON sin procesar."},"json.integers":{"en":"Convert an integer array into JSON array text.","es":"Convierte un arreglo de enteros en texto de arreglo JSON.","body":"numbers = [1, 2, 3]\nshow json.integers(numbers)","out":"[1,2,3]","noteEn":"Maximum 128 integers.","noteEs":"Máximo 128 enteros."},"json.valid":{"en":"Check whether the entire string contains valid JSON.","es":"Comprueba si toda la cadena contiene JSON válido.","body":"show json.valid(\"{\\\"score\\\":100}\")\nshow json.valid(\"{score:100}\")","out":"true\nfalse","noteEn":"Maximum input 4096 bytes; nesting depth limited to 32.","noteEs":"Máximo 4096 bytes de entrada y profundidad 32."},"json.get_raw":{"en":"Read the original JSON text of a top-level property.","es":"Lee el texto JSON original de una propiedad del objeto principal.","body":"profile = \"{\\\"name\\\":\\\"TRIPOL\\\",\\\"score\\\":100}\"\nshow json.get_raw(profile, \"name\")\nshow json.get_raw(profile, \"score\")","out":"\"TRIPOL\"\n100","noteEn":"Maximum 4096 bytes. String values retain their quotes. Missing or invalid properties return empty text; this is not a general object decoder.","noteEs":"Máximo 4096 bytes. Los valores de texto conservan sus comillas. Las propiedades ausentes o inválidas devuelven texto vacío; no es un decodificador general."},"json.get_raw_large":{"en":"Read a top-level property from a larger JSON document.","es":"Lee una propiedad del objeto principal de un documento JSON más grande.","body":"event = \"{\\\"data\\\":{\\\"score\\\":100}}\"\nshow json.get_raw_large(event, \"data\")","out":"{\"score\":100}","noteEn":"Maximum 65535 input bytes and 512 key bytes. Returns raw JSON, not a decoded object.","noteEs":"Máximo 65535 bytes de entrada y 512 bytes de clave. Devuelve JSON sin procesar, no un objeto decodificado."},"encoding.hex_digit":{"en":"Convert 0–15 to one hexadecimal digit.","es":"Convierte un entero entre 0 y 15 en un dígito hexadecimal.","body":"show encoding.hex_digit(15)","out":"f"},"encoding.hex_byte":{"en":"Convert a byte to two hexadecimal digits.","es":"Convierte un byte en dos dígitos hexadecimales.","body":"show encoding.hex_byte(255)","out":"ff"},"encoding.hex_int":{"en":"Convert a nonnegative integer into hexadecimal text.","es":"Convierte un entero no negativo en texto hexadecimal.","body":"show encoding.hex_int(256)","out":"100"},"encoding.hex_text":{"en":"Encode UTF-8 bytes as hexadecimal text.","es":"Codifica los bytes UTF-8 en texto hexadecimal.","body":"show encoding.hex_text(\"Hi\")","out":"4869","noteEn":"Maximum 1024 input bytes.","noteEs":"Máximo 1024 bytes de entrada."},"simd.equal":{"en":"Compare lengths and contents of two integer arrays.","es":"Compara la longitud y el contenido de dos arreglos de enteros.","body":"a = [1, 2]\nb = [1, 2]\nshow simd.equal(a, b)","out":"true"},"discord.run":{"en":"Start the bot and keep it connected to Discord to answer registered commands.","es":"Inicia el bot y lo mantiene conectado a Discord para responder comandos registrados.","body":"discord.login_env()\ndiscord.status(\"online\")\ndiscord.activity(\"TRIPOL\")\ndiscord.reply(\"!hola\", \"Hola!\")\ndiscord.run()","out":null,"noteEn":"Native Windows. Set DISCORD_TOKEN, enable Message Content Intent, invite the bot and grant permissions. Type !hola in a permitted channel. Stop with Ctrl+C; automatic reconnect is not supported.","noteEs":"Windows nativo. Configura DISCORD_TOKEN, activa Message Content Intent, invita al bot y concede permisos. Escribe !hola en un canal permitido. Detén con Ctrl+C; no hay reconexión automática.","returns":["Returns 1 after the Gateway loop closes normally; failures may stop execution.","Devuelve 1 cuando el bucle Gateway termina normalmente; los fallos pueden detener la ejecución."]},"discord.send":{"en":"Send a message using the token stored in the local environment.","es":"Envía un mensaje usando el token configurado en el entorno local.","body":"show discord.send(\"YOUR_CHANNEL_ID\", \"Hola!\")","out":null,"noteEn":"Replace the channel ID and set DISCORD_TOKEN. Requires permission to send messages. Message: 1–512 UTF-8 bytes.","noteEs":"Sustituye el ID y configura DISCORD_TOKEN. Requiere permiso para enviar mensajes. Mensaje: 1–512 bytes UTF-8.","returns":["True if the request returns a nonempty response; network errors may stop execution.","true si la petición devuelve una respuesta no vacía; los fallos de red pueden detener el programa."]},"discord.login_env":{"en":"Load the bot token from DISCORD_TOKEN into private local configuration.","es":"Carga el token de DISCORD_TOKEN en la configuración privada local.","body":"show discord.login_env()","out":"true","noteEn":"Set a valid-format token locally before running. This does not open a network connection.","noteEs":"Configura localmente un token con formato válido. Esto no abre una conexión de red."},"discord.login":{"en":"Configure the bot using a token supplied to the function.","es":"Configura el bot utilizando un token recibido por la función.","body":"secret = discord.token()\nshow discord.login(secret)","out":"true","noteEn":"Set DISCORD_TOKEN locally. Prefer login_env() for everyday use; never hardcode secrets. Configuration does not validate the token with Discord.","noteEs":"Configura DISCORD_TOKEN localmente. Prefiere login_env() para uso habitual; nunca escribas secretos en el código. Configurar no valida el token con Discord."},"discord.reply":{"en":"Register or replace the response to an exact command.","es":"Registra o reemplaza la respuesta de un comando exacto.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.preview(\"!hola\")","out":"Hola!","noteEn":"Maximum 16 commands; command 1–128 bytes, response 1–512 bytes.","noteEs":"Máximo 16 comandos; comando de 1–128 bytes, respuesta de 1–512 bytes."},"discord.preview":{"en":"Look up a registered command response without sending a message.","es":"Consulta una respuesta registrada sin enviar un mensaje.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.preview(\"!hola\")","out":"Hola!","noteEn":"","noteEs":"","returns":["Response text or empty text if no command matches.","Texto de respuesta o texto vacío si ningún comando coincide."]},"discord.channel":{"en":"Select the channel filter for incoming Gateway commands and the destination for say().","es":"Selecciona el filtro de canal para comandos Gateway y el destino de say().","body":"show discord.channel(\"123\")\nshow discord.has_channel()","out":"true\ntrue","noteEn":"The example only configures a numeric ID; use a real channel ID when connecting.","noteEs":"El ejemplo solo configura un ID numérico; usa un ID real al conectarte."},"discord.say":{"en":"Send a message to the currently selected channel.","es":"Envía un mensaje al canal seleccionado.","body":"discord.login_env()\ndiscord.channel(\"YOUR_CHANNEL_ID\")\nshow discord.say(\"Hola!\")","out":null,"noteEn":"Requires login, a real channel ID and permission to send messages.","noteEs":"Requiere iniciar sesión, un ID real y permiso para enviar mensajes."},"discord.send_to":{"en":"Send a message to a specific channel using the configured token.","es":"Envía un mensaje a un canal concreto utilizando el token configurado.","body":"discord.login_env()\nshow discord.send_to(\"YOUR_CHANNEL_ID\", \"Hola!\")","out":null,"noteEn":"Replace the ID, configure DISCORD_TOKEN and grant the bot channel permissions.","noteEs":"Sustituye el ID, configura DISCORD_TOKEN y concede permisos al bot."},"discord.token":{"en":"Read DISCORD_TOKEN from the local environment.","es":"Lee DISCORD_TOKEN desde el entorno local.","body":"secret = discord.token()\nshow len(secret) > 0","out":"true","noteEn":"Set DISCORD_TOKEN locally. This example checks that a token exists without revealing it. Never print the token itself.","noteEs":"Configura DISCORD_TOKEN localmente. El ejemplo comprueba que existe sin revelarlo. Nunca imprimas el token.","returns":["Secret token; do not display it.","Token secreto; no lo muestres."]},"discord.identify_payload":{"en":"Build the Gateway identification JSON, including the private token.","es":"Construye el JSON de identificación del Gateway, que incluye el token privado.","body":"discord.login_env()\npayload = discord.identify_payload()\nshow len(payload) > 0","out":"true","noteEn":"Advanced helper. The payload contains the token: never print, log or share it. run() calls this internally.","noteEs":"Función avanzada. El resultado contiene el token: nunca lo imprimas, registres ni compartas. run() lo utiliza internamente."},"discord.configured":{"en":"Check whether a token has been stored in the local bot configuration.","es":"Comprueba si hay un token guardado en la configuración local.","body":"discord.reset()\nshow discord.configured()","out":"false","noteEn":"A true result does not guarantee the token is accepted by Discord.","noteEs":"Un resultado true no garantiza que Discord acepte el token."},"discord.welcome":{"en":"Set a message to send once the Gateway is ready.","es":"Configura un mensaje que se envía cuando el Gateway está listo.","body":"discord.channel(\"123\")\nshow discord.welcome(\"Bot listo!\")","out":"true","noteEn":"Maximum 512 bytes. Select a real channel before run(); empty text disables the greeting.","noteEs":"Máximo 512 bytes. Selecciona un canal real antes de run(); el texto vacío desactiva el saludo."},"discord.connected":{"en":"Check the local Gateway ready state.","es":"Comprueba si el Gateway está listo según su estado local.","body":"discord.reset()\nshow discord.connected()","out":"false","noteEn":"This is a local state check, not a fresh network test.","noteEs":"Comprueba el estado local, no realiza una prueba de red nueva."},"discord.gateway":{"en":"Discover the public Discord Gateway address without a bot token.","es":"Consulta la dirección pública del Gateway de Discord sin utilizar un token.","body":"show discord.gateway()","out":null,"noteEn":"Requires an Internet connection and native HTTPS support. The response is JSON.","noteEs":"Requiere conexión a Internet y HTTPS nativo. La respuesta es JSON.","returns":["JSON returned by Discord.","JSON devuelto por Discord."]},"discord.api_host":{"en":"Get the hostname used by the Discord API.","es":"Obtiene el nombre del servidor de la API de Discord.","body":"show discord.api_host()","out":"discord.com","noteEn":"","noteEs":""},"discord.channel_path":{"en":"Build the API path used to access messages in a channel.","es":"Construye la ruta de la API que permite acceder a los mensajes de un canal.","body":"show discord.channel_path(\"123\")","out":"/api/v10/channels/123/messages","noteEn":"The channel ID must contain 1–20 digits. This example does not contact Discord.","noteEs":"El ID debe contener entre 1 y 20 dígitos. Este ejemplo no contacta con Discord."},"discord.latest":{"en":"Fetch the newest message in a channel as JSON.","es":"Obtiene el mensaje más reciente de un canal como JSON.","body":"message = discord.latest(\"YOUR_CHANNEL_ID\")\nshow len(message) > 0","out":null,"noteEn":"Set DISCORD_TOKEN and replace the ID. The bot needs access to the channel and message history.","noteEs":"Configura DISCORD_TOKEN y sustituye el ID. El bot necesita acceso al canal y al historial.","returns":["Message JSON or empty text if no usable message is found.","JSON del mensaje o texto vacío si no se encuentra un mensaje utilizable."]},"discord.message_id":{"en":"Extract a numeric ID from a message JSON object.","es":"Extrae el ID numérico de un mensaje JSON.","body":"message = \"{\\\"id\\\":\\\"123\\\"}\"\nshow discord.message_id(message)","out":"123","noteEn":"Returns zero if the ID is absent, invalid or outside the integer range.","noteEs":"Devuelve cero si el ID falta, no es válido o está fuera del rango entero."},"discord.matches":{"en":"Check whether a message is an exact command from a non-bot, non-webhook author.","es":"Comprueba si un mensaje coincide exactamente con un comando y no procede de un bot ni webhook.","body":"message = \"{\\\"id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}\"\nshow discord.matches(message, \"!hola\")\nshow discord.matches(message, \"!adios\")","out":"true\nfalse","noteEn":"","noteEs":""},"discord.listen":{"en":"Start a legacy bot loop for one command in one channel.","es":"Inicia un bot antiguo que escucha un único comando en un canal.","body":"discord.listen(\"YOUR_CHANNEL_ID\", \"!hola\", \"Hola!\")","out":null,"noteEn":"Native Windows REST polling; needs DISCORD_TOKEN and channel permissions. Polls the latest message every 2500 ms; use run() for Gateway bots. Stop with Ctrl+C.","noteEs":"Sondeo REST en Windows nativo; requiere DISCORD_TOKEN y permisos. Consulta el último mensaje cada 2500 ms; usa run() para bots Gateway. Detén con Ctrl+C."},"discord.reset":{"en":"Clear the local bot configuration, including token, commands and channel.","es":"Borra la configuración local del bot, incluidos token, comandos y canal.","body":"discord.reply(\"!hola\", \"Hola!\")\nshow discord.reset()\nshow discord.preview(\"!hola\") == \"\"","out":"true\ntrue","noteEn":"Does not delete anything on Discord.","noteEs":"No elimina nada en Discord."},"discord.dispatch":{"en":"Find the registered response to a raw message JSON without making a network request.","es":"Busca la respuesta registrada para un mensaje JSON sin realizar peticiones de red.","body":"discord.reply(\"!hola\", \"Hola!\")\nmessage = \"{\\\"id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}\"\nshow discord.dispatch(message)","out":"Hola!","noteEn":"Bot and webhook messages are ignored.","noteEs":"Se ignoran mensajes de bots y webhooks."},"discord.has_channel":{"en":"Check whether a channel has been selected.","es":"Comprueba si hay un canal seleccionado.","body":"discord.channel(\"123\")\nshow discord.has_channel()","out":"true","noteEn":"","noteEs":""},"discord.all_channels":{"en":"Remove the channel filter so Gateway replies can work in permitted channels.","es":"Elimina el filtro para responder en canales permitidos mediante Gateway.","body":"discord.channel(\"123\")\nshow discord.all_channels()\nshow discord.has_channel()","out":"true\nfalse","noteEn":"say() and welcome messages still require a selected channel.","noteEs":"say() y los mensajes de bienvenida siguen necesitando un canal seleccionado."},"discord.parse_latest":{"en":"Extract the first message object from a JSON array returned by REST.","es":"Extrae el primer objeto de mensaje de un arreglo JSON devuelto por REST.","body":"result = \"[{\\\"id\\\":\\\"123\\\"},{\\\"id\\\":\\\"456\\\"}]\"\nshow discord.parse_latest(result)","out":"{\"id\":\"123\"}","noteEn":"","noteEs":"","returns":["First object as JSON or empty text on invalid input.","Primer objeto como JSON o texto vacío si la entrada no es válida."]},"discord.run_rest":{"en":"Start the legacy REST polling loop using the configured channel and commands.","es":"Inicia el bucle antiguo de sondeo REST con el canal y comandos configurados.","body":"discord.login_env()\ndiscord.channel(\"YOUR_CHANNEL_ID\")\ndiscord.reply(\"!hola\", \"Hola!\")\ndiscord.run_rest()","out":null,"noteEn":"Native Windows. Requires a selected channel, token and permissions. Polls the newest message; stop with Ctrl+C.","noteEs":"Windows nativo. Requiere canal, token y permisos. Consulta el último mensaje; detén con Ctrl+C."},"discord.setup":{"en":"Configure the token and channel in one call.","es":"Configura el token y el canal en una sola llamada.","body":"secret = discord.token()\nshow discord.setup(secret, \"123\")","out":"true","noteEn":"Configure DISCORD_TOKEN locally; replace 123 with the real ID for live use. No network connection is opened.","noteEs":"Configura DISCORD_TOKEN localmente; sustituye 123 por el ID real para conectarte. No abre una conexión."},"discord.status":{"en":"Choose the presence status sent when the bot identifies itself to Discord.","es":"Elige el estado de presencia que se envía al identificarse el bot.","body":"show discord.status(\"idle\")","out":"true","noteEn":"Allowed: online, idle, dnd, invisible. Configure before run().","noteEs":"Permitidos: online, idle, dnd, invisible. Configura antes de run()."},"discord.activity":{"en":"Choose the activity text displayed by the bot when connecting.","es":"Elige el texto de actividad que muestra el bot al conectarse.","body":"show discord.activity(\"Programando con TRIPOL\")","out":"true","noteEn":"Maximum 128 UTF-8 bytes; empty text clears the activity.","noteEs":"Máximo 128 bytes UTF-8; el texto vacío elimina la actividad."},"discord.ping":{"en":"Get the most recent Gateway heartbeat round-trip time in milliseconds.","es":"Obtiene la última latencia de heartbeat del Gateway en milisegundos.","body":"discord.reset()\nshow discord.ping()","out":"-1","noteEn":"Returns -1 until a heartbeat acknowledgement is recorded.","noteEs":"Devuelve -1 hasta que se registra una confirmación de heartbeat."},"discord.heartbeat_payload":{"en":"Build the JSON heartbeat for a Gateway sequence number.","es":"Construye el JSON de heartbeat para un número de secuencia.","body":"show discord.heartbeat_payload(7)\nshow discord.heartbeat_payload(-1)","out":"{\"op\":1,\"d\":7}\n{\"op\":1,\"d\":null}","noteEn":"Advanced protocol helper; run() sends heartbeats automatically.","noteEs":"Función avanzada del protocolo; run() envía heartbeats automáticamente."},"discord.event_channel":{"en":"Extract the channel ID of a MESSAGE_CREATE Gateway event and apply the channel filter.","es":"Extrae el ID de canal de un evento Gateway MESSAGE_CREATE y aplica el filtro de canal.","body":"event = \"{\\\"op\\\":0,\\\"t\\\":\\\"MESSAGE_CREATE\\\",\\\"d\\\":{\\\"channel_id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}}\"\nshow discord.event_channel(event)","out":"123","noteEn":"","noteEs":"","returns":["Channel ID text or empty text if the event is rejected.","ID de canal como texto o texto vacío si el evento se rechaza."]},"discord.gateway_reply":{"en":"Resolve a registered reply from a Gateway event without opening a connection.","es":"Busca la respuesta registrada para un evento Gateway sin abrir una conexión.","body":"discord.reply(\"!hola\", \"Hola!\")\nevent = \"{\\\"op\\\":0,\\\"t\\\":\\\"MESSAGE_CREATE\\\",\\\"d\\\":{\\\"channel_id\\\":\\\"123\\\",\\\"content\\\":\\\"!hola\\\",\\\"author\\\":{\\\"bot\\\":false}}}\"\nshow discord.gateway_reply(event)","out":"Hola!","noteEn":"Ignores bots, webhooks and events outside the configured channel filter.","noteEs":"Ignora bots, webhooks y eventos fuera del filtro de canal."},"json.ws":{"en":"Skip JSON whitespace from a byte offset.","es":"Salta los espacios en blanco JSON desde un índice de bytes.","body":"s = \"  42\"\nshow json.ws(s, 0, len(s))","out":"2","noteEn":"Advanced scanner helper; offsets start at zero and n is the exclusive end.","noteEs":"Función avanzada del analizador; los índices empiezan en cero y n es el límite exclusivo."},"json.hex":{"en":"Check whether a byte is an ASCII hexadecimal digit.","es":"Comprueba si un byte es un dígito hexadecimal ASCII.","body":"show json.hex(65)\nshow json.hex(71)","out":"true\nfalse","noteEn":"65 is A, 71 is G.","noteEs":"65 representa A y 71 representa G."},"json.digit":{"en":"Check whether a byte is an ASCII decimal digit.","es":"Comprueba si un byte es un dígito decimal ASCII.","body":"show json.digit(57)\nshow json.digit(65)","out":"true\nfalse","noteEn":"57 is 9, 65 is A.","noteEs":"57 representa 9 y 65 representa A."},"json.quoted":{"en":"Scan a JSON quoted string and return the byte offset immediately after it.","es":"Analiza una cadena JSON entre comillas y devuelve el índice de bytes justo después de ella.","body":"s = \"\\\"hola\\\"\"\nshow json.quoted(s, 0, len(s))","out":"6","noteEn":"Returns -1 if the string is invalid. Use quote() for creating strings.","noteEs":"Devuelve -1 si la cadena no es válida. Usa quote() para crear cadenas."},"json.literal":{"en":"Match a literal token at the current byte offset.","es":"Comprueba si un literal coincide desde el índice de bytes indicado.","body":"s = \"true\"\nshow json.literal(s, 0, len(s), \"true\")\nshow json.literal(s, 0, len(s), \"null\")","out":"4\n-1","noteEn":"Returns the offset after the match or -1. It does not validate a complete JSON document.","noteEs":"Devuelve el índice posterior a la coincidencia o -1. No valida un documento JSON completo."},"json.number":{"en":"Scan a JSON number and return where it ends, without converting it to a number.","es":"Analiza un número JSON y devuelve dónde termina, sin convertirlo a un número.","body":"s = \"-12.5\"\nshow json.number(s, 0, len(s))","out":"5","noteEn":"Returns -1 for invalid number syntax; use valid() to validate the complete input.","noteEs":"Devuelve -1 para sintaxis numérica inválida; usa valid() para validar toda la entrada."},"json.value":{"en":"Scan one JSON value (object, array, number, string, boolean or null).","es":"Analiza un valor JSON (objeto, arreglo, número, texto, booleano o null).","body":"s = \"[1,2]\"\nshow json.value(s, 0, len(s), 0)","out":"5","noteEn":"Advanced scanner; returns the next byte offset or -1. Nesting is limited to depth 32.","noteEs":"Analizador avanzado; devuelve el siguiente índice de bytes o -1. Profundidad máxima 32."}};
const LEARNING_STATUS={"animation":"executed","arrays":"executed","binary":"executed","bits":"executed","bitset":"executed","buffer":"executed","camera":"executed","canvas":"executed","checksum":"executed","collections":"executed","colors":"executed","compression":"executed","console":"executed","convert":"executed","datetime":"executed","dictionary":"executed","discord":"compiler-rejected","encoding":"executed","env":"compiler-rejected","errors":"executed","events":"compiler-rejected","files":"executed","game":"compiler-rejected","geometry":"executed","http":"compiled-only","https":"compiler-rejected","image":"executed","json":"executed","math":"executed","matrix":"executed","memory":"executed","network":"compiled-only","particles":"executed","path":"executed","physics":"executed","profiler":"compiled-only","queue":"executed","random":"executed","search":"executed","sequences":"executed","simd":"executed","sort":"executed","sprite":"executed","stack":"executed","stats":"executed","system":"executed","testing":"executed","text":"executed","time":"compiled-only","ui":"compiler-rejected","validate":"executed","vector":"executed"};

function learningReference(){
 const match=location.pathname.match(/\/docs\/libraries\/([^/]+)\.html$/);if(!match)return;
 const lib=match[1],article=$('.docs-article');if(!article)return;
 const data=LEARNING_GUIDES,status=LEARNING_STATUS[lib]||'unknown';
 const make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el};
 const bilingual=(en,es)=>{const el=make('span','',en);el.dataset.es=es;return el};
 const title=(en,es)=>{const el=make('strong');el.append(bilingual(en,es));return el};
 const types={int:['64-bit integer','Entero de 64 bits'],bool:['Boolean (true or false)','Booleano (true o false)'],string:['Text (UTF-8)','Texto (UTF-8)'],float:['Decimal number','Número decimal'],ints:['Integer array','Arreglo de enteros'],list:['List','Lista'],void:['No value','Sin valor'],string_list:['Text list','Lista de textos'],bool_list:['Boolean list','Lista de booleanos'],float_list:['Decimal list','Lista de decimales']};
 function splitParams(s){let out=[],part='',depth=0,quote='',esc=false;for(const c of s){if(quote){part+=c;if(esc)esc=false;else if(c==='\\')esc=true;else if(c===quote)quote='';continue}if(c==='"'||c==="'"){quote=c;part+=c;continue}if('([{'.includes(c))depth++;if(')]}'.includes(c))depth--;if(c===','&&depth===0){out.push(part.trim());part=''}else part+=c}if(part.trim())out.push(part.trim());return out}
 const guide=make('div','doc-lib-guide');guide.dataset.webStatus=status;
 const labels={executed:['The main library example ran in Web Engine R3. Individual functions may differ.','El ejemplo principal se ejecutó en Web Engine R3. Algunas funciones pueden diferir.'],'compiler-rejected':['The main example requires native TRIPOL; browser execution is unavailable.','El ejemplo principal requiere TRIPOL nativo; no se puede ejecutar en el navegador.'],'compiled-only':['The main example compiled for WASM; execution was not verified.','El ejemplo principal compiló para WASM; la ejecución no está verificada.'],unknown:['Web compatibility has not been verified.','La compatibilidad web no está verificada.']};
 const note=make('p');note.append(bilingual(...labels[status]||labels.unknown));
 const source=make('a');source.href='https://github.com/Tripollas/Tripol/blob/main/stdlib/'+lib+'.tri';source.target='_blank';source.rel='noopener noreferrer';source.append(bilingual('View library source on GitHub ↗','Ver código fuente de la biblioteca en GitHub ↗'));guide.append(note,source);article.querySelector('.lib-meta')?.after(guide);
 for(const card of article.querySelectorAll('.function-card')){
  const signature=card.querySelector('pre.signature');if(!signature)continue;
  const parsed=signature.textContent.trim().match(/^func\s+[\w.]+\s*\(([\s\S]*)\)\s*(?:->\s*([\w]+))?\s*$/);
  for(const details of card.querySelectorAll('details')){if(details.querySelector('pre'))details.remove()}
  const row=data[lib+'.'+card.id];if(row){const p=card.querySelector('p');if(p)p.replaceChildren(bilingual(row.en,row.es))}
  if(parsed){
   const box=make('div','doc-function-info'),params=make('div'),returns=make('div');params.append(title('Parameters','Parámetros'));returns.append(title('Returns','Devuelve'));
   const args=splitParams(parsed[1]);if(!args.length){const p=make('p','doc-empty');p.append(bilingual('No arguments.','No recibe argumentos.'));params.append(p)}else{
    const dl=make('dl','doc-params');for(const arg of args){const m=arg.match(/^(\w+)(?:\s*:\s*(\w+))?(?:\s*=\s*([\s\S]+))?$/);const r=make('div'),dt=make('dt'),dd=make('dd');dt.append(make('code','',m?m[1]:arg));if(m){dd.append(bilingual(...(m[2]?(types[m[2]]||[m[2],m[2]]):['Inferred type','Tipo inferido'])));if(m[3]!==undefined){dd.append(' · ',bilingual('Default','Predeterminado'),': ',make('code','',m[3]))}}r.append(dt,dd);dl.append(r)}params.append(dl)
   }
   const ret=parsed[2]||'void',p=make('p','doc-empty');p.append(make('code','',ret),' · ',bilingual(...(types[ret]||[ret,ret])));returns.append(p);if(row?.returns){const meaning=make('p','doc-empty');meaning.append(bilingual(...row.returns));returns.append(meaning)}box.append(params,returns);card.append(box)
  }
  if(row?.body){const h=make('h4','doc-example-title');h.append(bilingual('Usage example','Ejemplo de uso'));const pre=make('pre','doc-usage');pre.append(make('code','language-tripol','import tripol.'+lib+'\n\n'+row.body));card.append(h,pre);
   if(row.out!==null&&row.out!==undefined){const out=make('div','doc-expected'),p=make('pre');p.append(make('code','language-output',row.out));out.append(title('Expected output','Resultado esperado'),p);card.append(out)}
  }
  if(row?.noteEn){const p=make('p','doc-function-note');p.append(bilingual(row.noteEn,row.noteEs));card.append(p)}
 }
}

learningReference();
$$('.docs-article pre').forEach(pre=>{if(pre.classList.contains('signature'))return;const shell=document.createElement('div');shell.className='code-shell';const head=document.createElement('div');head.className='code-head';const title=document.createElement('span');const mode=codeMode(pre.querySelector('code')||pre);title.textContent=mode==='tripol'?'TRIPOL':['cmd','sh','bash','shell','powershell','ps1'].includes(mode)?(mode==='powershell'?'POWERSHELL':'TERMINAL'):mode==='text'?'CODE':mode.toUpperCase();const copy=document.createElement('button');copy.className='doc-copy';copy.dataset.es='Copiar';copy.textContent='Copy';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(pre.textContent);toast(translate('Copied to clipboard','Copiado al portapapeles'))}catch{const range=document.createRange();range.selectNodeContents(pre);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast(translate('Selected — copy manually','Seleccionado — copia manualmente'))}});head.append(title,copy);pre.before(shell);shell.append(head,pre)});
function buildToc(){const target=$('#toc-links');target.replaceChildren();$$('.docs-article h2,.docs-article .function-card h3').forEach((h,i)=>{const id=h.id||h.closest('.function-card')?.id||('section-'+i);if(!h.id&&!h.closest('.function-card'))h.id=id;const a=document.createElement('a');a.href='#'+id;a.textContent=h.textContent.replace(/\s*#\s*$/,'');if(h.tagName==='H3')a.className='sub';target.append(a)});}
installAllLive();registerLabels();apply();$('#doc-lang').addEventListener('click',()=>{lang=lang==='en'?'es':'en';apply()});
$('#doc-menu').addEventListener('click',()=>{$('#doc-menu').setAttribute('aria-expanded',String(side.classList.toggle('open')))});
$('#side-filter').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();$$('.side-libs a').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q))});
const lf=$('#library-filter');if(lf)lf.addEventListener('input',()=>{let n=0;const q=lf.value.trim().toLowerCase();$$('.library-card').forEach(a=>{a.hidden=!a.dataset.filter.toLowerCase().includes(q);if(!a.hidden)n++});$('#library-empty').hidden=!!n});
const dialog=$('#doc-search'),input=$('#global-search');
function renderSearch(){const q=input.value.trim().toLowerCase();const list=DOC_SEARCH.filter(item=>[item.title,item.detail,item.es||''].join(' ').toLowerCase().includes(q)).slice(0,30);const results=$('#search-results');results.replaceChildren();if(!list.length){const p=document.createElement('p');p.textContent=translate('No results. Try a library or function name.','Sin resultados. Prueba una biblioteca o función.');results.append(p);return}list.forEach(item=>{const a=document.createElement('a');a.className='search-item';const u=new URL(root+item.url,location.href);u.searchParams.set('lang',lang);a.href=u.href;const title=document.createElement('strong');title.textContent=item.title;const detail=document.createElement('small');detail.textContent=lang==='es'&&item.es?item.es:item.detail;a.append(title,detail);results.append(a)})}
function openSearch(){if(!dialog.open)dialog.showModal();renderSearch();input.focus()}
$('#search-open').addEventListener('click',openSearch);$('#search-close').addEventListener('click',()=>dialog.close());input.addEventListener('input',renderSearch);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#search-results a')?.focus()}else if(e.key==='Enter')$('#search-results a')?.click()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'&&side.classList.contains('open')){side.classList.remove('open');$('#doc-menu').setAttribute('aria-expanded','false')}});
const active=side.querySelector('[aria-current=page]');if(active&&active.offsetTop>side.clientHeight-90)side.scrollTop=active.offsetTop-100;
})();
